<script setup>
import { computed, ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileBottomNav from '../../../components/mds/MMobileBottomNav.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue';
const props=defineProps({rows:{type:Array,default:()=>[]},total:Number,page:Number,pageSize:Number,search:String,canCreate:Boolean,safeAreaStyle:{type:Object,default:()=>({})},nativeNavigation:{type:Array,default:()=>[]}});const emit=defineEmits(['back','search','page','open','create','navigate']);const query=ref(props.search||'');const chooser=ref(false);watch(()=>props.search,(value)=>{query.value=value||'';});const primaryKeys=new Set(['dashboard','people','interactions','events']);const primaryNavigation=computed(()=>[...props.nativeNavigation.filter((item)=>primaryKeys.has(item.key)),{key:'more',label:'Khác',icon:'dots-circle-horizontal',active:false}]);const moreNavigation=computed(()=>props.nativeNavigation.filter((item)=>!primaryKeys.has(item.key)));function submit(){emit('search',query.value.trim());}function navigate(key){if(key==='more'){chooser.value=true;return;}emit('navigate',key);}function navigateMore(key){chooser.value=false;emit('navigate',key);}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Nhà cung cấp" @back="emit('back')"><template #actions><MButton v-if="canCreate" variant="link" @click="emit('create')">Thêm</MButton></template></MMobileTopBar><form class="mds-mobile-gutter-x flex shrink-0 gap-2 border-b border-[var(--mds-border-light)] py-3" @submit.prevent="submit"><MInput v-model="query" placeholder="Tìm nhà cung cấp…"/><MButton variant="primary" @click="submit">Tìm</MButton></form><main class="min-h-0 flex-1 overflow-y-auto pb-[calc(var(--mds-mobile-bottom-nav-height)+var(--mds-mobile-safe-bottom))]"><div v-if="rows.length" class="divide-y divide-[var(--mds-border-light)]"><MButton v-for="row in rows" :key="row.id" variant="link" class="mds-mobile-gutter-x flex min-h-[var(--mds-mobile-touch-target)] w-full items-center justify-start py-3 text-left" @click="emit('open',row.id)"><span class="min-w-0 flex-1"><strong class="block truncate text-[14px] text-[var(--mds-text)]">{{ row.name }}</strong><span class="mt-0.5 block truncate text-[13px] text-[var(--mds-text-secondary)]">{{ row.industry }} · {{ row.services }}</span></span></MButton></div><MEmptyState v-else title="Chưa có nhà cung cấp" description="Thử đổi từ khóa hoặc tạo mới."/></main><footer class="flex shrink-0 justify-between border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pt-3"><span class="self-center text-[12px] text-[var(--mds-text-secondary)]">{{ total }} nhà cung cấp</span><span></span></footer><MMobileBottomNav :items="primaryNavigation" @navigate="navigate"/></section><MDialog v-model="chooser" title="Khác" confirm-text="Đóng"><div class="grid gap-2"><MButton v-for="item in moreNavigation" :key="item.key" variant="neutral" class="[&]:w-full [&]:justify-start" :disabled="item.disabled" @click="navigateMore(item.key)">{{ item.label }}</MButton></div></MDialog></template>
